import "./Hello.css";

export default function Hello() {
    function showName() {
        console.log("Mike");
    }
    function showAge(age) {
        console.log(age);
    }
    function showText(e) {
        console.log(e.target.vlaue);
    }
    return (
        <div className = "helloBox">
        <h1>Hello</h1>
        <button onClick = {showName()}>Show name</button>
        <input
        type = "text"
        onChange= {e => {
            const txt =e.target.value;
            showText(txt);
        }}
        />
        </div>
    );
}
